-- Fraud Detection Power BI Practice Dataset v2
-- Generated for learning/practice purposes.
-- Relationship design:
-- transactions 1 -> many fraud_alerts
-- fraud_rules 1 -> many fraud_alerts
-- transactions 1 -> 1 transaction_risk (only for transactions with >=1 alert)
-- transaction_risk is consolidated from fraud_alerts + fraud_rules.risk_points

CREATE DATABASE IF NOT EXISTS fraud_detection;
USE fraud_detection;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS transaction_risk;
DROP TABLE IF EXISTS fraud_alerts;
DROP TABLE IF EXISTS fraud_rules;
DROP TABLE IF EXISTS transactions;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE transactions (
    txn_id INT PRIMARY KEY,
    user_id INT NOT NULL,
    txn_time DATETIME NOT NULL,
    amount DECIMAL(12,2) NOT NULL,
    merchant_type VARCHAR(50) NOT NULL,
    txn_type VARCHAR(30) NOT NULL,
    device VARCHAR(100) NOT NULL,
    location VARCHAR(100) NOT NULL,
    ip_address VARCHAR(45) NOT NULL
);

CREATE TABLE fraud_rules (
    rule_id INT PRIMARY KEY,
    rule_name VARCHAR(100) NOT NULL,
    description VARCHAR(255),
    risk_points INT NOT NULL,
    severity VARCHAR(20) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE fraud_alerts (
    alert_id INT PRIMARY KEY,
    txn_id INT NOT NULL,
    user_id INT NOT NULL,
    rule_id INT NOT NULL,
    alert_time DATETIME NOT NULL,
    status VARCHAR(20) NOT NULL,
    CONSTRAINT fk_alert_txn FOREIGN KEY (txn_id) REFERENCES transactions(txn_id),
    CONSTRAINT fk_alert_rule FOREIGN KEY (rule_id) REFERENCES fraud_rules(rule_id)
);

CREATE TABLE transaction_risk (
    txn_id INT PRIMARY KEY,
    user_id INT NOT NULL,
    risk_score INT NOT NULL,
    risk_level VARCHAR(20) NOT NULL,
    calculated_at DATETIME NOT NULL,
    CONSTRAINT fk_risk_txn FOREIGN KEY (txn_id) REFERENCES transactions(txn_id)
);

CREATE INDEX idx_transactions_user ON transactions(user_id);
CREATE INDEX idx_transactions_time ON transactions(txn_time);
CREATE INDEX idx_transactions_ip ON transactions(ip_address);
CREATE INDEX idx_alerts_txn ON fraud_alerts(txn_id);
CREATE INDEX idx_alerts_rule ON fraud_alerts(rule_id);
CREATE INDEX idx_alerts_status ON fraud_alerts(status);
CREATE INDEX idx_risk_level ON transaction_risk(risk_level);

