-- Validation queries
SELECT COUNT(*) AS total_transactions FROM transactions;
SELECT COUNT(*) AS total_rules FROM fraud_rules;
SELECT COUNT(*) AS total_alerts FROM fraud_alerts;
SELECT COUNT(*) AS alerted_transactions FROM transaction_risk;

SELECT
    a.txn_id,
    SUM(r.risk_points) AS calculated_risk_score
FROM fraud_alerts a
JOIN fraud_rules r ON a.rule_id = r.rule_id
GROUP BY a.txn_id
ORDER BY a.txn_id
LIMIT 20;
